#include <bits/stdc++.h>
using namespace std;
class Solution {public:int peopleAwareOfSecret(int n,int delay,int forget){const long long M=1000000007;vector<long long> dp(n+1);dp[1]=1;long long active=0;for(int day=2;day<=n;++day){if(day-delay>=1)active=(active+dp[day-delay])%M;if(day-forget>=1)active=(active-dp[day-forget]+M)%M;dp[day]=active;}long long ans=0;for(int i=max(1,n-forget+1);i<=n;++i)ans=(ans+dp[i])%M;return ans;}};
